import isAuthorizedToAutoApply from '../helpers/autoApplyAccess'

export default function withAutoApplyAuthorization<T extends Record<string, any>, R>(
  fn: (this: T, ...args: any[]) => Promise<R>,
): (this: T, ...args: any[]) => Promise<R | void> {
  return async function (this: T, ...args: any[]): Promise<R | void> {
    const { jtrack_user: user } = await chrome.storage.local.get(['jtrack_user'])

    const { isLoggedIn } = isAuthorizedToAutoApply(user)
    if (!isLoggedIn) return

    return fn.apply(this, args)
  }
}
