import withAutoApplyAuthorization from '../../decorators/userLoggedInDecorator'
import isAuthorizedToAutoApply from '../../helpers/autoApplyAccess'
import { CAREER_IO_APP_DOMAIN, JOB_TRACKING_URL, RESUME_IO_DOMAIN } from '../../shared/constants'
import { JobBoardPost } from '../../shared/types'
import { AUTO_APPLY_BUTTON_ID, TAB_MESSAGE_TYPES } from '../constants'
import { Board } from './types'

const resumeIoIconSrc = chrome.runtime.getURL('careerio.svg')

const DISABLED_CLASS_NAME = 'disabled'
const LOADING_STATE = 'Loading...'
export class BaseJobBoard {
  constructor() {}

  REFRESH_TIME_MS = 500
  removeButtons(): void {
    const cioApplyContainers = document.querySelectorAll(`#${AUTO_APPLY_BUTTON_ID}-container`)

    cioApplyContainers.forEach((el) => {
      el.remove()
    })
  }

  createBtnHtml(text: string, disabled = false, index?: number): string {
    const tootTipText = 'AutoApply not necessary. Please use the 1-click apply button instead.'
    const tooltip = disabled ? `<div class="custom-tooltip">${tootTipText}</div>` : ''

    const btnHtml = `<div id="${AUTO_APPLY_BUTTON_ID}-container">${tooltip}<button alt="Auto Apply" ${
      disabled ? `disabled` : ''
    } 
 class=${disabled ? DISABLED_CLASS_NAME : ''} data-index=${index} id="${AUTO_APPLY_BUTTON_ID}">
    <img src=${resumeIoIconSrc} alt="CIO icon"/><span>${text}</span>
    </button></div>`

    return btnHtml
  }

  handleAutoApplyResponse(response): void {
    const buttonIndex = response.buttonIndex
    const suffix = `${buttonIndex ? `[data-test="${buttonIndex}"]` : ''}`
    const cioQuickApplyButton = document.querySelector(
      `button[id^="${AUTO_APPLY_BUTTON_ID}"]${suffix}`,
    ) as HTMLButtonElement

    const btnLabel = document.querySelector(
      `button[id^="${AUTO_APPLY_BUTTON_ID}"]${suffix} span`,
    ) as HTMLButtonElement

    if (response.success) {
      window.open(JOB_TRACKING_URL(response.baseDomain), '_blank')
      btnLabel.innerHTML = 'AutoApply'
    } else {
      btnLabel.innerHTML = 'AutoApply'
      cioQuickApplyButton.disabled = true
      cioQuickApplyButton.classList.add(DISABLED_CLASS_NAME)
    }

    if (response.redirectTo) {
      window.open(response.redirectTo, '_blank')
    }
  }

  scrapeJobDetails(index?: number): JobBoardPost {
    return
  }

  @withAutoApplyAuthorization
  async insertAutoApplyButton() {}

  async updateButtonState() {
    const cioQuickApplyButtons = document.querySelectorAll(
      `button[id^="${AUTO_APPLY_BUTTON_ID}"]`,
    ) as NodeListOf<HTMLButtonElement>

    if (!cioQuickApplyButtons.length) return

    const { jtrack_user: user } = await chrome.storage.local.get(['jtrack_user'])
    const { isLoggedIn } = isAuthorizedToAutoApply(user)

    if (!isLoggedIn) return this.removeButtons()

    cioQuickApplyButtons.forEach((button) => {
      const buttonIndex = Number(button.getAttribute('data-index')) || undefined
      const jobDetails = this.scrapeJobDetails(buttonIndex)

      const btnLabel = button.querySelector('span') as HTMLSpanElement

      if (btnLabel && btnLabel.innerHTML === LOADING_STATE) {
        btnLabel.innerHTML = 'AutoApply'

        button.addEventListener('click', function () {
          btnLabel.innerHTML = LOADING_STATE
          chrome.runtime.sendMessage({
            type: TAB_MESSAGE_TYPES.autoApply,
            url: window.location.href,
            jobDetails,
            buttonIndex,
          })
        })
      }
    })
  }
  addEventListeners() {}

  startLoadingContent() {
    let lastPath = window.location.href
    let isInitialRender = true

    setInterval(async () => {
      const { jtrack_user: user } = await chrome.storage.local.get(['jtrack_user'])
      const { isLoggedIn } = isAuthorizedToAutoApply(user)

      if (!isLoggedIn) return this.removeButtons()
      const pathChanged = lastPath !== window.location.href
      if (pathChanged) {
        this.removeButtons()
      }

      await this.insertAutoApplyButton()
      await this.updateButtonState()

      if (pathChanged) {
        lastPath = window.location.href
      }

      if (isInitialRender) {
        isInitialRender = false
      }
      this.addEventListeners()
    }, 500)
  }

  async messageListener(request, sender, sendResponse, board: Board) {
    switch (request.type) {
      case TAB_MESSAGE_TYPES.sendJwt:
        setTimeout(async () => await board.updateButtonState(), board.REFRESH_TIME_MS)
        return
      case TAB_MESSAGE_TYPES.autoApplyResponse:
        this.handleAutoApplyResponse(request.response)
        return
      case TAB_MESSAGE_TYPES.scrapeJobDetails:
        sendResponse({ job: board.scrapeJobDetails() })
        return
    }
  }
}
