import { JobBoardPost } from '../../shared/types'
import { AUTO_APPLY_BUTTON_ID } from '../constants'
import { BaseJobBoard } from './base'

const INDEED_APPLY_BUTTON_ID = 'viewJobButtonLinkContainer'

export default class IndeedJobBoard extends BaseJobBoard {
  async insertAutoApplyButton() {
    const alreadyInserted = document.getElementById(AUTO_APPLY_BUTTON_ID)

    let applyContainers = document.querySelectorAll(`#${INDEED_APPLY_BUTTON_ID}`)

    if (!applyContainers.length) {
      applyContainers = document.querySelectorAll(
        '#jobsearch-ViewJobButtons-container > div:has(span[data-indeed-apply-jk])',
      )
    }

    const isEasyApplyJob = !document.querySelectorAll(`#${INDEED_APPLY_BUTTON_ID}`).length

    if (alreadyInserted || !applyContainers.length) return

    applyContainers.forEach((saveButton) => {
      const cioAutoApplyButton = this.createBtnHtml('Loading...', isEasyApplyJob)

      saveButton?.insertAdjacentHTML('beforebegin', cioAutoApplyButton)
    })
  }

  scrapeJobDetails(): JobBoardPost {
    const applyButton = document.querySelector(
      '#applyButtonLinkContainer button',
    ) as HTMLButtonElement | null
    const jobId = document
      .querySelector('#jobsearch-ViewJobButtons-container span[data-indeed-apply-jk]')
      ?.getAttribute('data-indeed-apply-jk')
    const link = applyButton?.getAttribute('href')
      ? applyButton?.getAttribute('href')
      : jobId
        ? `https://indeed.com/viewjob?jk=${jobId}`
        : null

    if (!link) return

    const indeedTitle = document.querySelector('.jobsearch-JobInfoHeader-title')?.textContent

    const definedLocation = document.querySelector(
      'div[data-testid="inlineHeader-companyLocation',
    )?.textContent
    const generalJobLocationText = document.querySelector(
      'div[data-testid="inlineHeader-companyName"]',
    )?.parentElement?.parentElement?.childNodes[1].textContent

    const location = definedLocation ? definedLocation : generalJobLocationText
    return {
      description: document.querySelector('#jobDescriptionText')?.textContent || '',
      title: indeedTitle ? indeedTitle.split('- job post')[0] : '',
      link,
      company:
        document.querySelector('div[data-testid="inlineHeader-companyName"]')?.textContent || '',
      location: location || '',
    }
  }
}
